package com.example.callsentry;
import android.content.*;import java.io.*;import java.net.*;import java.nio.charset.*;import java.text.*;import java.util.*;
class FtcSync{static int sync(Context c,int days){ScamDb db=new ScamDb(c);int added=0;Calendar cal=Calendar.getInstance(TimeZone.getTimeZone("America/New_York"));for(int i=0;i<days;i++){Calendar x=(Calendar)cal.clone();x.add(Calendar.DAY_OF_YEAR,-i);String date=String.format(Locale.US,"%1$tY-%1$tm-%1$td",x);String u="https://www.ftc.gov/sites/default/files/DNC_Complaint_Numbers_"+date+".csv";HttpURLConnection h=null;try{h=(HttpURLConnection)new URL(u).openConnection();h.setConnectTimeout(5000);h.setReadTimeout(15000);h.setRequestProperty("User-Agent","CallSentry/1.0");if(h.getResponseCode()!=200)continue;BufferedReader r=new BufferedReader(new InputStreamReader(h.getInputStream(),StandardCharsets.UTF_8));String head=r.readLine();if(head==null)continue;String line;while((line=r.readLine())!=null){String[] p=parse(line);if(p.length<2)continue;String n=p[0];long day=parseDay(p[1]);if(day>0){db.add(n,day);added++;}}r.close();}catch(Exception ignored){}finally{if(h!=null)h.disconnect();}}db.meta("last_sync",new SimpleDateFormat("MMM d, yyyy h:mm a",Locale.US).format(new Date()));return added;}
 static long parseDay(String s){String[] fm={"yyyy-MM-dd HH:mm:ss","yyyy-MM-dd","MM/dd/yyyy"};for(String f:fm)try{return new SimpleDateFormat(f,Locale.US).parse(s).getTime()/86400000L;}catch(Exception ignored){}return 0;}
 static String[] parse(String s){ArrayList<String>a=new ArrayList<>();StringBuilder b=new StringBuilder();boolean q=false;for(int i=0;i<s.length();i++){char c=s.charAt(i);if(c=='\"'){if(q&&i+1<s.length()&&s.charAt(i+1)=='\"'){b.append('\"');i++;}else q=!q;}else if(c==','&&!q){a.add(b.toString());b.setLength(0);}else b.append(c);}a.add(b.toString());return a.toArray(new String[0]);}}
